class _Bubble extends StatelessWidget {
  const _Bubble({
    required this.p,
    required this.text,
    required this.mine,
    this.name,
    this.time,
    this.image = false,
  });

  final DesignPalette p;
  final String text;
  final bool mine;
  final String? name;
  final String? time;
  final bool image;

  @override
  Widget build(BuildContext context) {
    final double maxW = MediaQuery.sizeOf(context).width * 0.72;
    final Widget bubble = Container(
      constraints: BoxConstraints(maxWidth: maxW),
      padding: const EdgeInsets.fromLTRB(12, 10, 12, 10),
      decoration: BoxDecoration(
        color: mine ? p.primarySoft : p.surface,
        borderRadius: BorderRadius.circular(14),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          if (image) ...<Widget>[
            Container(
              height: 76,
              decoration: BoxDecoration(
                color: p.surface2,
                borderRadius: BorderRadius.circular(10),
              ),
              child: Center(
                  child: Icon(Icons.image_outlined, size: 26, color: p.muted)),
            ),
            const SizedBox(height: 8),
          ],
          Text(text,
              style: TextStyle(fontSize: 12.5, height: 1.35, color: p.text)),
        ],
      ),
    );
    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: Row(
        mainAxisAlignment:
            mine ? MainAxisAlignment.end : MainAxisAlignment.start,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          if (!mine) ...<Widget>[
            CircleAvatar(
              radius: 14,
              backgroundColor: p.surface2,
              child: Text(name == null || name!.isEmpty ? '?' : name!.substring(0, 1),
                  style: TextStyle(fontSize: 11, color: p.muted)),
            ),
            const SizedBox(width: 8),
          ],
          Column(
            crossAxisAlignment:
                mine ? CrossAxisAlignment.end : CrossAxisAlignment.start,
            children: <Widget>[
              if (name != null)
                Padding(
                  padding: const EdgeInsets.only(bottom: 4, left: 2),
                  child: Text(name!,
                      style: TextStyle(
                          fontSize: 10.5,
                          fontWeight: FontWeight.w600,
                          color: p.muted)),
                ),
              bubble,
              if (time != null)
                Padding(
                  padding: const EdgeInsets.only(top: 4, right: 2),
                  child: Text(time!,
                      style: TextStyle(fontSize: 10, color: p.dim)),
                ),
            ],
          ),
        ],
      ),
    );
  }
}

